-- 0280 vinos_pdf (inventario_vinos_pdf) — borra placeholder + entidades + puntuaciones reales
DELETE FROM puntuaciones WHERE categoria='vinos';
DELETE FROM entidades WHERE fuente='inventario_vinos_pdf';
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11020','vino','Vinos y bodegas','La gran catedral mundial del vino generoso. Ofrece imponentes bodegas históricas de techos monumentales como González Byass o Domecq y el sistema tradicional de criaderas y soleras.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11032','vino','Vinos y bodegas','Cuna exclusiva de la Manzanilla. Sus bodegas (como Barbadillo o Hidalgo La Gitana) miran al Atlántico y combinan catas únicas con el ambiente pesquero de Bajo de Guía.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('11027','vino','Vinos y bodegas','Tercer vértice del triángulo del Jerez. Alberga bodegas majestuosas y muy potentes a nivel turístico como Gutiérrez Colosía u Osborne, con su famoso toro.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16007','vino','Vinos y bodegas','Aunque es conocida por su costa playera, conserva pequeños lagares familiares tradicionales y cooperativas que elaboran finos y moscateles locales con mucho encanto.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90032','vino','Vinos y bodegas','Famosa por sus moscateles dulces tradicionales. Cuenta con bodegas cooperativas históricas y pequeños despachos de vino integrados en el pueblo.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14042','vino','Vinos y bodegas','Epicentro de la D.O. Montilla-Moriles. Destaca por sus bodegas de crianza bajo velo de flor y lagares en la sierra que elaboran espectaculares vinos finos y amontillados de uva Pedro Ximénez.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('14045','vino','Vinos y bodegas','Comparte el corazón de la denominación. Destacan sus cooperativas y pequeños lagares de campo tradicionales que ofrecen visitas muy auténticas e industriales.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17001','vino','Vinos y bodegas','Pequeño municipio olivarero y vitícola con bodegas tradicionales que atesoran antiquísimos amontillados en un entorno monumental.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90460','vino','Vinos y bodegas','Capital de la D.O. Condado de Huelva. Alberga el Centro del Vino y potentes bodegas familiares e industriales que elaboran el vino blanco de uva Zalema y vinos naranjas.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21054','vino','Vinos y bodegas','Municipio histórico de gran tradición bodeguera. Cuenta con espectaculares destilerías de brandy y cooperativas vinícolas visitables.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29084','vino','Vinos y bodegas','Una de las zonas emergentes más bonitas. Sus bodegas "boutique" (como Descalzos Viejos, en un antiguo convento) producen tintos de altura rodeados de un imponente paisaje serrano.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29045','vino','Vinos y bodegas','Pueblo blanco de la Axarquía famoso por sus vinos dulces de uva Moscatel de Alejandría cultivada en pendientes imposibles. Conserva una tradicional e histórica Noche del Vino.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04014','vino','Vinos y bodegas','Centro de los Vinos de la Tierra de Almería en la Alpujarra. Cuenta con varias bodegas modernas rodeadas de viñedos de montaña de gran altitud.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04071','vino','Vinos y bodegas','Pequeño municipio alpujarreño con bodegas artesanales que rescatan variedades autóctonas en bancales y parajes naturales únicos.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50073','vino','Vinos y bodegas','Da nombre a una de las D.O. más antiguas de España. Cuenta con un gran Museo del Vino, la Fiesta de la Vendimia y potentes complejos industriales como Grandes Vinos.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49001','vino','Vinos y bodegas','Municipio clave de la D.O. Campo de Borja. Alberga importantes bodegas cooperativas potentes donde la reina absoluta es la uva Garnacha.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22048','vino','Vinos y bodegas','Capital de la D.O. Somontano. Es una ruta enoturística muy potente con bodegas vanguardistas de renombre internacional como Viñas del Vero, Blecua o Enate (que fusiona vino y arte).','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22202','vino','Vinos y bodegas','Pequeño municipio vecino que alberga bodegas innovadoras perfectamente integradas en el paisaje prepirenaico.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35018','vino','Vinos y bodegas','Uno de los paisajes enoturísticos más impactantes del planeta en la isla de Lanzarote. Los viñedos de Malvasía se cultivan en hoyos de ceniza volcánica protegidos por muros circulares de piedra.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35034','vino','Vinos y bodegas','Municipio que comparte el espacio de La Geria. Alberga algunas de las bodegas operativas más antiguas de las islas (como El Grifo) con museos excelentes.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38026','vino','Vinos y bodegas','Famoso por su sistema único de cultivo en Cordón Trenzado. Ofrece bodegas familiares enclavadas en casonas coloniales con vistas directas al Teide.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13018','vino','Vinos y bodegas','Ciudad del vino por excelencia con siglos de historia. Ofrece museos dedicados al sector, grandes complejos industriales y bodegas tradicionales que aún conservan tinajas gigantes de barro.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13017','vino','Vinos y bodegas','Municipio con una inmensa infraestructura vinícola. Destaca por sus chimeneas de destilación alcoholera industriales y sus cuevas subterráneas tradicionales excavadas para la crianza.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02005','vino','Vinos y bodegas','Da nombre a su propia D.O. Destaca por sus potentes vinos tintos de uva Garnacha Tintorera y sus bodegas enfocadas a la exportación e internacionalización.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02033','vino','Vinos y bodegas','Pequeña localidad de tradición puramente cooperativista donde se producen vinos de alta calidad en un entorno rural manchego.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47114','vino','Vinos y bodegas','Corazón indiscutible de la D.O. Ribera del Duero. Destaca su Castillo medieval (que acoge el Museo Provincial del Vino) y la vanguardista e imponente bodega de Protos excavada en la montaña.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47139','vino','Vinos y bodegas','Cuna del vino blanco Verdejo. Sus terrenos llanos esconden inmensas bodegas subterráneas de la época mudéjar (como el Hilo de Ariadna) combinadas con modernas plantas industriales.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47129','vino','Vinos y bodegas','Ubicado en la "Milla de Oro" de la Ribera del Duero. Municipio pequeño pero de valor extremo al albergar firmas míticas de prestigio mundial como Pingus o Arzuaga.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47101','vino','Vinos y bodegas','Municipio histórico de la D.O. Rueda. Posee un patrimonio subterráneo monumental con calados antiguos inmensos y bodegas tradicionales de crianza.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09001','vino','Vinos y bodegas','Famosa a nivel mundial por sus 7 kilómetros de bodegas subterráneas medievales (siglo XIV) que recorren el subsuelo del centro de la villa. Centro neurálgico del lechazo y el vino.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09016','vino','Vinos y bodegas','Sede del Consejo Regulador de la D.O. Ribera del Duero. Ofrece un magnífico mirador sobre el río Duero y bodegas industriales y tecnológicas de primer nivel.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09256','vino','Vinos y bodegas','Pueblo pequeño pero con una altísima concentración de viñedos viejos y bodegas de enorme prestigio familiar e histórico (como Pago de los Capellanes o Rodero).','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49219','vino','Vinos y bodegas','Capital de su propia denominación. Famosa por sus tintos potentes y con cuerpo. El municipio cuenta con iglesias monumentales, calados históricos bajo las casas y firmas potentes como Numanthia.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49129','vino','Vinos y bodegas','Localidad vecina que concentra un Museo del Vino muy didáctico y bodegas familiares de larga trayectoria en la zona.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08240','vino','Vinos y bodegas','La capital indiscutible del Cava. Cuenta con más de 80 bodegas locales, destacando los gigantes Codorníu (joya modernista declarada Monumento Nacional) y Freixenet, con kilómetros de túneles.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('08305','vino','Vinos y bodegas','Capital del vino del Penedès. Sede del Vinseum (Museo de las Culturas del Vino de Cataluña) y de potentes firmas internacionales como Bodegas Torres.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43055','vino','Vinos y bodegas','Capital de la prestigiosa y mística D.O.C. Priorat. Rodeada de un paisaje abrupto de viñedos en terrazas sobre suelos de pizarra (llicorella). Destaca su bodega cooperativa de estilo modernista.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43069','vino','Vinos y bodegas','Municipio pequeño pero clave en la revolución del Priorat. Cuenta con una altísima densidad de bodegas de culto internacionales creadas por los "pioneros" del vino de la zona.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43106','vino','Vinos y bodegas','Alberga la espectacular "Catedral del Vino", una obra cooperativa modernista diseñada por Cèsar Martinell con un impresionante friso cerámico exterior.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36004','vino','Vinos y bodegas','Capital histórica del vino Albariño (D.O. Rías Baixas). El enoturismo se disfruta entre pazos señoriales.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('36027','vino','Vinos y bodegas','Municipio plenamente rural en el Valle del Salnés. Repleto de pequeñas bodegas familiares (furanchos) y viñedos de minifundio costero.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32069','vino','Vinos y bodegas','Capital de la D.O. Ribeiro. Su precioso barrio judío medieval creció gracias al histórico comercio del vino. Combina bodegas termales y pequeños elaboradores artesanales (colleiteiros).','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90556','vino','Vinos y bodegas','Integrado en la D.O. Ribeira Sacra. Ofrece viñedos en pendientes verticales extremas sobre el río Sil, dando lugar a la espectacular "viticultura heroica".','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26071','vino','Vinos y bodegas','Sede del famoso Barrio de la Estación, la mayor concentración de bodegas centenarias del mundo (Muga, CVNE, Viña Tondonia). Epicentro mundial de la Rioja Alta.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26089','vino','Vinos y bodegas','La capital autonómica combina su famosa ruta gastronómica de la Calle Laurel con grandes bodegas urbanas históricas como Marqués de Murrieta o Ontañón.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26034','vino','Vinos y bodegas','Hermoso pueblo medieval que alberga el Museo Vivanco de la Cultura del Vino, considerado uno de los mejores y más completos del mundo.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26129','vino','Vinos y bodegas','Cuna de los vinos claretes tradicionales. Cuenta con un barrio histórico de bodegas horadadas en el cerro por los propios agricultores.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01031','vino','Vinos y bodegas','Máxima puntuación. Villa medieval amurallada cuyo subsuelo está totalmente excavado por calados históricos. Cuenta con paisajes infinitos y bodegas vanguardistas de autor como Ysios (diseño de Calatrava).','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('01022','vino','Vinos y bodegas','Sede de Marqués de Riscal. Su espectacular "Ciudad del Vino" cuenta con el icónico hotel diseñado por Frank Gehry en láminas de titanio rosa y oro.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30022','vino','Vinos y bodegas','Municipio con una imponente tradición vinícola marcada por la uva Monastrell. Cuenta con una Ruta del Vino oficial que integra bodegas modernas de exportación y viñedos de secano.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30043','vino','Vinos y bodegas','Da nombre a su propia D.O. Cuenta con un marcado carácter industrial enfocado al vino y bodegas cooperativas de enorme volumen técnico.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24002','vino','Vinos y bodegas','Destaca por albergar proyectos excelentes como Bodegas Marcelino Serrano. Elaboran vinos tintos y blancos recuperando variedades autóctonas y ofreciendo catas artesanales muy cuidadas a los pies de su patrimonio histórico.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23033','vino','Vinos y bodegas','Sede de Bodegas Campoameno, una de las pioneras de la I.G.P. Sierra Sur de Jaén. Un entorno de montaña ideal para ver viñedos de altura cultivados en zonas tradicionalmente copadas por el olivar.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('23088','vino','Vinos y bodegas','Epicentro de la I.G.P. Tierra de Torreperogil. Cuenta con cooperativas locales de larga tradición que producen tintos y blancos jóvenes con un fuerte arraigo cultural en la comarca.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19001','vino','Vinos y bodegas','Viñedos situados a gran altitud que producen caldos recios de montaña. Conserva bodegas familiares singulares como Aranzada donde se experimenta con crianzas naturales.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18161','vino','Vinos y bodegas','Un minúsculo pueblo en la falda de Sierra Nevada donde micro-bodegas locales elaboran vinos ecológicos de altura de excelente nivel en un paraje natural asombroso.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90405','vino','Vinos y bodegas','Pequeño rincón de la Alpujarra almeriense donde la bodega local mantiene viva la tradición de los viñedos viejos en laderas desérticas de pizarra.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('41032','vino','Vinos y bodegas','Aunque históricamente fue famosa por sus destilerías de aguardiente y anís, hoy en día varias bodegas boutique han recuperado la tradición del viñedo en plena Sierra Norte de Sevilla.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28133','vino','Vinos y bodegas','El pulmón garnachero de Madrid. Aunque pequeño, esconde bodegas con un potencial enorme como Las Moradas de San Martín, ubicadas entre formaciones de granito y viñedos centenarios.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('28031','vino','Vinos y bodegas','Cooperativas e iniciativas independientes que cultivan viñas viejas de montaña recuperando el valor del paisaje serrano madrileño.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05057','vino','Vinos y bodegas','Epicentro de la pujante D.O.P. Cebreros. Pequeños viticultores locales están fascinando al sector con vinificaciones artesanales de Garnacha vieja y Albillo Real sobre suelos de pizarra y granito en la Sierra de Gredos.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05241','vino','Vinos y bodegas','Localidad vecina repleta de microproyectos ecológicos y bodegas biodinámicas en un entorno natural rodeado de castaños y pinares.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39055','vino','Vinos y bodegas','Capital de la comarca de Liébana. Aprovecha un microclima mediterráneo dentro de los Picos de Europa para cultivar viñedos tradicionales en ladera. Es ideal para combinar la cata de vinos de la tierra con la visita a alquitaras tradicionales de orujo.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05006','vino','Vinos y bodegas','Sede de la D.O.P. Cangas. Un ejemplo radical de viticultura heroica en el norte de España. El enoturismo se vive entre pendientes que superan el 60% de inclinación sobre suelos de pizarra, elaborando tintos con variedades autóctonas como el Albarín Negro o el Mencía.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19192','vino','Vinos y bodegas','Da nombre a una pequeña D.O. local. Municipio puramente agrícola que esconde bodegas históricas de corte familiar centradas en la uva autóctona Malvar.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06023','vino','Vinos y bodegas','Enmarcado en la D.O. Ribera del Guadiana. Pequeñas bodegas industriales familiares que mezclan la visita vitícola con su imponente patrimonio histórico y ganadero.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('22039','vino','Vinos y bodegas','Pequeñas bodegas situadas al pie de los Mallos de Riglos que producen vinos con carácter bajo la I.G.P. Ribera del Gállego-Cinco Villas.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90037','vino','Vinos y bodegas','Ubicado en la emblemática comarca de la Contraviesa-Alpujarra. Esconde bodegas diminutas enclavadas en terrenos de montaña donde la uva Vigiriega se cultiva entre almendros e higueras a más de 1.000 metros de altitud.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('49065','vino','Vinos y bodegas','Conocido popularmente como el "Pueblo de las 1.000 Bodegas". Todo el subsuelo de este municipio histórico en el Parque Natural de Arribes del Duero está completamente horadado por túneles y bodegas ancestrales excavadas en granito vivo.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47159','vino','Vinos y bodegas','Integrado en la Ruta del Vino de Rueda. Destaca por sus queserías artesanales y por bodegas singulares como Bodegas de Alberto, que mantiene calados medievales intactos y la elaboración tradicional del vino dorado bajo el sol en damajuanas. [1, 2, 3].','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47065','vino','Vinos y bodegas','Custodia la curiosa Bodega de Plastilina, un espacio didáctico y museístico subterráneo único en la zona enfocado al turismo familiar. [1, 2].','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17034','vino','Vinos y bodegas','Cuenta con una arraigada tradición de "vino de payés". Sus masías tradicionales.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17041','vino','Vinos y bodegas','Municipio fronterizo en la Sierra de la Albera repleto de pequeños productores independientes que elaboran vinos con un marcado carácter marcado por el viento de Tramuntana.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46213','vino','Vinos y bodegas','Aunque Requena es grande, pedanías y zonas como San Antonio albergan bodegas boutique y hoteles enológicos de alta calidad centrados en la uva Bobal y elaboraciones orgánicas.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29068','vino','Vinos y bodegas','Sus viñedos de Moscatel de Alejandría miran directamente al mar Mediterráneo. Cuenta con el Centro de Interpretación del Vino (CIVIMA) y pequeñas bodegas familiares que producen vinos blancos secos excelentes.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29072','vino','Vinos y bodegas','Concentra gran parte de la producción de vino de la provincia de Málaga. Su gran cooperativa es un motor industrial potente y cuenta con visitas muy didácticas sobre vinos tranquilos y generosos.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('29086','vino','Vinos y bodegas','Pequeño pueblo blanco de la Axarquía con viñedos en pendientes brutales donde se elaboran vinos artesanos y pasas de forma totalmente tradicional.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18179','vino','Vinos y bodegas','Situado en la Alpujarra profunda. Alberga bodegas que trabajan con viñedos de altura extremos (hasta 1.300 metros), produciendo caldos con una concentración y un carácter mineral únicos.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18048','vino','Vinos y bodegas','Cuenta con micro-bodegas locales que, de manera muy humilde y fuera del circuito de masas, producen vinos tranquilos para consumo comarcal.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04010','vino','Vinos y bodegas','En pleno corazón del Valle del Andarax. Sus bodegas familiares organizan catas rodeadas de montañas nevadas y viñedos de cepas viejas.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47098','vino','Vinos y bodegas','Famoso por su Aula de Interpretación de las Bodegas y su espectacular barrio de bodegas subterráneas del siglo XVI. Es el auténtico bastión del vino clarete (D.O. Cigales).','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47050','vino','Vinos y bodegas','Da nombre a su propia D.O. Es una parada obligatoria gracias a sus imponentes bodegas históricas y cooperativas que defienden el auténtico vino clarete. Cuenta con un entramado de túneles bajo el casco urbano fascinante para el turismo tradicional.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47066','vino','Vinos y bodegas','Muy cerca de la capital, mezcla su imponente castillo con pequeños restaurantes con bodegas excavadas ideales para degustar vinos de la comarca.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47158','vino','Vinos y bodegas','Es el municipio con mayor superficie de viñedo de toda Castilla y León. Cuenta con firmas potentísimas a nivel enoturístico e industrial dedicadas al Verdejo.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34022','vino','Vinos y bodegas','Alberga el espectacular Barrio de las Bodegas de Baltanás, un conjunto de 378 bodegas subterráneas excavadas en un cerro arcilloso que forman un paisaje exterior único que parece de cuento.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('34182','vino','Vinos y bodegas','Localidad de la D.O. Arlanza con una inmensa concentración de lagares y bodegas de piedra tradicionales que reflejan el pasado histórico vinícola de la zona.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09008','vino','Vinos y bodegas','Municipio monumental que acoge bodegas de la D.O. Arlanza. El enoturismo aquí es de corte señorial, uniendo la historia del palacio ducal con los vinos tintos de la comarca.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09151','vino','Vinos y bodegas','Villa medieval de la Ribera del Duero que esconde bodegas espectaculares de arquitectura de vanguardia (como Bodegas Portia, diseñada por Norman Foster).','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42162','vino','Vinos y bodegas','El pulmón de la Ribera del Duero en Soria. Su barrio de bodegas tradicionales al pie del castillo convive con viñedos viejísimos (muchos prefiloxéricos) que producen tintos de altísima finura.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('26007','vino','Vinos y bodegas','Epicentro de la D.O. Bierzo. Rodeado por el Camino de Santiago, cuenta con grandes sedes vinícolas, el Palacio de Canedo (Prada a Tope) y espectaculares viñedos emparrados de uva Mencía y Godello.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('24187','vino','Vinos y bodegas','Famoso por sus cuevas subterráneas reconvertidas en restaurantes donde se consume el tradicional vino Prieto Picudo, un tinto/rosado muy característico elaborado con la técnica del "madreo".','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45099','vino','Vinos y bodegas','Municipio histórico que da nombre a su D.O. Posee bodegas de corte tradicional manchego mezcladas con nuevos proyectos ecológicos enfocados en la uva Garnacha.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('45054','vino','Vinos y bodegas','Cuenta con una de las mayores superficies de viñedo de Europa. Sus cooperativas e industrias del vino son gigantescas, moviendo millones de litros al año.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02008','vino','Vinos y bodegas','Situado en la D.O. Manchuela. Un pequeño gran bastión de la uva Bobal donde bodegas familiares (como Vega Tolosa) elaboran vinos ecológicos de proyección internacional.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16113','vino','Vinos y bodegas','Localidad marcadamente agraria con cooperativas masivas de tecnificación avanzada capaces de procesar volúmenes industriales brutales de uva.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46249','vino','Vinos y bodegas','Núcleo histórico de la D.O. Utiel-Requena. Alberga el Museo de la Vid y el Vino (Bodega Redonda) y monumentales bodegas subterráneas de la época medieval perfectamente visitables.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90374','vino','Vinos y bodegas','Conocida como la "Toscana Valenciana". Un precioso paisaje de masías y viñedos donde se asientan bodegas boutique de altísimo nivel (como Celler del Roure) que han recuperado las tinajas de barro bajo tierra.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06004','vino','Vinos y bodegas','Ciudad internacional del vino y sede de la D.O. Ribera del Guadiana. Es, además, la única localidad de Extremadura autorizada para elaborar el Cava de forma oficial, con un potente tejido industrial y museístico.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06149','vino','Vinos y bodegas','Conocida como la "Ciudad de la Música", posee una gran tradición enológica con bodegas familiares rodeadas de llanuras interminables de viñedos arcillosos.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43064','vino','Vinos y bodegas','Capital de la D.O. Terra Alta. Su principal atractivo enoturístico es su Cooperativa Modernista, una obra de arte arquitectónica construida en 1919 con espectaculares bóvedas de ladrillo.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43114','vino','Vinos y bodegas','En la D.O.C. Priorat. Un pueblo de poetas y viticultores donde las bodegas están metidas en los bajos de las casas de piedra y las viñas escalan laderas imposibles de pizarra.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90523','vino','Vinos y bodegas','Enclavado en el corazón del Ribeiro. Ofrece un paisaje precioso de viñedos ladera abajo hasta el embalse, combinando pequeños cosecheros con actividades náuticas y enológicas.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32085','vino','Vinos y bodegas','Sede de la D.O. Monterrei. El enoturismo se disfruta a la sombra del gran castillo medieval, visitando bodegas industriales y pequeñas bodegas familiares que producen excelentes blancos de uva Godello.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90648','vino','Vinos y bodegas','Capital de la principal D.O. mallorquina. Sus bodegas (como José L. Ferrer) están construidas con la característica piedra de la zona y elaboran vinos con variedades autóctonas muy singulares como Manto Negro y Moll.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90652','vino','Vinos y bodegas','Pequeño municipio de tradición artesana vecino de Binissalem con pequeñas bodegas boutique enfocadas en visitas privadas e íntimas.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47179','vino','Vinos y bodegas','Uno de los grandes templos mundiales del vino. En su término municipal se encuentra la mítica bodega Vega Sicilia. Además, alberga el Monasterio de Santa María de Valbuena, sede permanente de Las Edades del Hombre y un hotel-balneario de vinoterapia de altísimo lujo.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47163','vino','Vinos y bodegas','Aunque es famosísimo por sus campos de lavanda, este pequeño municipio de los Montes Torozos cuenta con una bodega singular e innovadora (Bodega Pago de Trascasas) que ofrece catas exclusivas combinadas con turismo rural y observación astronómica.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09004','vino','Vinos y bodegas','Cuna de Santo Domingo de Guzmán. Este bellísimo conjunto monumental esconde una de las bodegas subterráneas visitables más antiguas de la Ribera del Duero (siglo XII), ubicada en el Convento de las Dominicas.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('09228','vino','Vinos y bodegas','Un caso de éxito mundial en el enoturismo. Este pequeño pueblo recuperó su "Cotarro de Bodegas": un cerro que concentra 157 bodegas subterráneas y 7 lagares tradicionales perfectamente restaurados. Ganó el premio de la Unión Europea al Patrimonio Cultural.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90227','vino','Vinos y bodegas','Municipio volcado con el enoturismo de la D.O. León. Alberga el MUMI (Museo de la Industria Harinera) y las imponentes Bodegas Gordonzello, donde se organizan paseos guiados entre viñedos de las variedades autóctonas Prieto Picudo y Albarín.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04058','vino','Vinos y bodegas','Un pequeño pueblo de la Sierra de los Filabres que cuenta con micro-bodegas artesanales. Destacan por elaborar vinos tintos de garaje de producción limitadísima con cepas cultivadas en bancales de piedra.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('18035','vino','Vinos y bodegas','En pleno corazón de la Alpujarra granadina. Custodia bodegas con mucha solera como Barranco Oscuro, pionera en España en la elaboración de vinos naturales sin sulfitos añadidos a casi 1.300 metros de altitud sobre el nivel del mar.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21061','vino','Vinos y bodegas','Posee una arquitectura bodeguera preciosa de estilo regionalista. Sus cooperativas y bodegas familiares (como Bodegas Contreras Ruiz) combinan la tradición del vino de la D.O. Condado de Huelva con un enoturismo muy vinculado a Doñana.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16171','vino','Vinos y bodegas','Famoso por su ruta de arte urbano y murales, este municipio manchego cuenta con bodegas cooperativas de enormes dimensiones donde se puede aprender sobre los procesos modernos de vinificación a gran escala técnica.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('13016','vino','Vinos y bodegas','Sede de la Torre del Vino, un museo enoturístico ultra-moderno con mirador interactivo. El municipio cuenta con potentes e históricas bodegas familiares y una de las mayores superficies de viñedo tecnificado del país.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('44141','vino','Vinos y bodegas','Ubicado en la bellísima comarca del Matarraña (la "Toscana aragonesa"). Esconde proyectos enológicos fascinantes como Venta d''Abert, una bodega de corte ecológico y experimental que elabora vinos de altísima calidad fuera de las denominaciones tradicionales.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50067','vino','Vinos y bodegas','Capital de su propia D.O. Destaca por su enoturismo de contrastes: desde las grandes e industriales bodegas cooperativas de San Alejandro en Miedes, hasta sus viñedos viejos de Garnacha plantados en laderas de pizarra a gran altitud.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('46022','vino','Vinos y bodegas','En las faldas de la Sierra de Mariola, este precioso y pequeño pueblo esconde pequeños productores de aceite y micro-bodegas artesanales que recuperan vinos rústicos tradicionales elaborados en prensa de piedra.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27059','vino','Vinos y bodegas','Es uno de los municipios estrella de la D.O. Ribeira Sacra (subzona de Amandi). Concentra espectaculares miradores sobre los cañones del río Sil y un gran número de bodegas donde los viticultores desafían la gravedad en laderas verticales para recoger la uva Mencía.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90818','vino','Vinos y bodegas','Vecino de la zona de Cigales, este pequeño municipio destaca por albergar bodegas de corte muy familiar y tradicional excavadas en la tierra arcillosa, ideales para visitas íntimas y catas directas de barrica.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('47045','vino','Vinos y bodegas','Ubicado en un entorno natural precioso junto a la Reserva Natural de las Riberas de Castronuño. Alberga bodegas integradas en el paisaje que aprovechan el microclima del río Duero para elaborar tintos y blancos orgánicos muy singulares.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42103','vino','Vinos y bodegas','Municipio histórico que marca la entrada del Duero en tierras sorianas. Cuenta con un barrio de bodegas tradicionales al pie de su torre medieval y es una de las pocas localidades de Soria que elabora Cava de forma oficial dentro de la D.O.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40215','vino','Vinos y bodegas','Capital de la pequeña e independiente D.O.P. Valtiendas. Situado a más de 900 metros de altitud, sus pequeños viticultores producen tintos de uva Tempranillo con una potencia y un frescor que están sorprendiendo a los críticos.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40148','vino','Vinos y bodegas','Enclavado en la D.O. Rueda pero dentro de la provincia de Segovia. Es un rincón mágico porque esconde viñedos viejísimos de uva Verdejo plantados en pie franco (que sobrevivieron a la filoxera) sobre suelos muy arenosos.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21074','vino','Vinos y bodegas','Alberga algunas de las cooperativas y bodegas más antiguas de la comarca del Condado de Huelva. Su patrimonio arquitectónico está totalmente ligado a los lagares y a la producción artesana del vino blanco de uva Zalema.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('21047','vino','Vinos y bodegas','Curiosamente, da nombre al famoso vino aunque no se produce aquí (se hace en Sanlúcar). Es un pueblo puramente agrícola con pequeñas bodegas cooperativas que surten de mosto y vino base a las grandes zonas de crianza.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('04018','vino','Vinos y bodegas','Famosísimo históricamente por la "Uva de Ohanes" o uva de barco (que se exportaba a todo el mundo). Hoy en día, pequeños agricultores locales luchan por recuperar la tradición artesana elaborando vinos de mesa en pequeñas bodegas de montaña.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50169','vino','Vinos y bodegas','Municipio integrado en la D.O. Calatayud. Alberga cooperativas monumentales y muy potentes a nivel industrial (como Bodegas San Alejandro) que exportan vinos de Garnacha vieja a decenas de países y ofrecen visitas técnicas excelentes.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('50136','vino','Vinos y bodegas','Situado en la comarca del Bajo Martín. Cuenta con cooperativas e iniciativas ecológicas independientes que cultivan variedades tradicionales en un clima semiárido extremo, logrando tintos con mucha extracción.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90055','vino','Vinos y bodegas','Considerado la cuna del Txakoli de Vizcaya. Es un destino enoturístico precioso de costa donde los.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('48037','vino','Vinos y bodegas','En el interior de las Encartaciones, este municipio alberga bodegas boutique tecnológicas ocultas entre caseríos tradicionales vascos, ideales para catar blancos con una marcada acidez atlántica.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25034','vino','Vinos y bodegas','Un municipio donde el enoturismo convive con paisajes pre-pirenaicos. Destaca por albergar cooperativas potentes y bodegas de diseño que experimentan con variedades internacionales y maduraciones lentas de montaña.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('25097','vino','Vinos y bodegas','Micro-pueblo de Les Garrigues que esconde pequeñas bodegas cooperativas de producción limitada enfocadas en el cultivo ecológico y la mínima intervención bajo el sol de Ponent.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('10044','vino','Vinos y bodegas','Ubicado en el Geoparque VilluercasIbores-Jara. Es el gran bastión histórico del vino en Cáceres dentro de la D.O. Ribera del Guadiana. Sus bodegas familiares destacan por los tradicionales vinos de pitarra y blancos afrutados de altura.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27016','vino','Vinos y bodegas','Uno de los grandes epicentros de la viticultura heroica. Sus viñas caen en pendientes verticales hacia el río Miño. Alberga bodegas tecnológicas y familiares excelentes (como Vía Romana) que producen Mencía y Godello de gran finura.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27058','vino','Vinos y bodegas','Municipio ribereño repleto de románico y pequeños productores de vino. Destaca por sus paisajes de viñedos en bancales y catas íntimas en bodegas integradas en antiguas casas de piedra.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('27041','vino','Vinos y bodegas','Zona con una alta concentración de monasterios y bodegas boutique. Sus suelos graníticos aportan una mineralidad espectacular a los vinos blancos y tintos de la comarca.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90514','vino','Vinos y bodegas','La capital indiscutible del vino Godello de alta gama. Sus bodegas combinan naves industriales modernas con antiguos calados excavados en tierra arcillosa, ideales para comprender el éxito internacional de estos blancos.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32072','vino','Vinos y bodegas','Municipio vecino clave en Valdeorras. Cuenta con una gran tradición cooperativista y bodegas históricas situadas en un entorno de montaña marcado por la pizarra y el paso del río Sil.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('32040','vino','Vinos y bodegas','En pleno corazón del Ribeiro. Destaca por albergar pazos monumentales reconvertidos en bodegas e iniciativas de jóvenes viticultores que recuperan castas autóctonas como la Treixadura.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90525','vino','Vinos y bodegas','Localidad puramente rural donde el viñedo de minifundio trepa por las colinas. Esconde micro-bodegas artesanales y alojamientos de enoturismo rural de gran belleza.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33028','vino','Vinos y bodegas','Municipio limítrofe con Galicia que comparte la tradición de la viticultura heroica asturiana. Pequeños paisanos mantienen viñedos viejos en laderas imposibles de pizarra para elaborar vinos de fuerte carácter atlántico.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('33073','vino','Vinos y bodegas','Aunque es una zona eminentemente ganadera, cuenta con pequeñas parcelas testimoniales de viñedo de montaña vinculadas a la cultura tradicional del vino de la zona occidental.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39020','vino','Vinos y bodegas','En la costa oriental, varias bodegas boutique han recuperado el viñedo costero, elaborando vinos blancos con uvas como la Albariño y la Hondarrabi Zuri con una marcada salinidad marina.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('39015','vino','Vinos y bodegas','Ubicado en el Valle de Liébana. Pequeños lagares familiares destilan el famoso orujo en alquitaras de cobre y producen vinos tintos de mesa en un microclima de montaña único.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37284','vino','Vinos y bodegas','Epicentro de la uva autóctona Rufete. Un pueblo serrano precioso donde las viñas crecen en terrazas rodeadas de castaños. Alberga cooperativas modernizadas y bodegas de garaje de gran prestigio ecológico.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37364','vino','Vinos y bodegas','Situado en los Arribes del Duero. Destaca por su gigantesco patrimonio de bodegas subterráneas excavadas en roca granítica bajo las casas del pueblo y sus vinos de la variedad Juan García.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37008','vino','Vinos y bodegas','Villa medieval amurallada que cuenta con bodegas integradas en la arquitectura tradicional, uniendo el turismo histórico con catas de vinos tintos muy fluidos y atlánticos.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('37250','vino','Vinos y bodegas','Municipio de los Arribes con una potente cooperativa local que elabora vinos potentes y ofrece miradores espectaculares sobre los cañones del río Duero.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40058','vino','Vinos y bodegas','Municipio segoviano integrado en la D.O. Rueda. Destaca por sus grandes extensiones de viñedo de Verdejo gestionadas por familias del pueblo y cooperativas de la zona.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('40174','vino','Vinos y bodegas','Famoso por su lechazo asado, cuenta con un consolidado barrio de bodegas tradicionales excavadas en el cerro donde los agricultores elaboran de forma artesanal vinos tintos recios.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05201','vino','Vinos y bodegas','Zona alta de la Sierra de Gredos donde se cultivan viñedos viejos de Garnacha a casi 1.000 metros de altitud. Destacan las micro-bodegas de mínima intervención y vinos de culto.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('05156','vino','Vinos y bodegas','Pequeño municipio de tradición agrícola con pequeñas explotaciones vitícolas familiares orientadas a la producción de vinos artesanos y ecológicos.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16060','vino','Vinos y bodegas','Sede de la D.O. Ribera del Júcar. Cuenta con bodegas familiares de gran empuje turístico e industrial que trabajan con viñedos centenarios de uva Bobal plantados sobre suelos de cantos rodados.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16175','vino','Vinos y bodegas','Municipio eminentemente agrícola con una de las cooperativas más grandes de la provincia, equipada con tecnología de última generación para procesar millones de kilos de uva.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('16166','vino','Vinos y bodegas','Pequeña localidad manchega cuyo paisaje está dominado por viñas y olivos. Alberga bodegas de estructura tradicional familiar orientadas al mercado nacional.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02056','vino','Vinos y bodegas','Municipio adscrito a la D.O. Jumilla. Destaca por sus vinos potentes de uva Monastrell y una gran cooperativa que organiza visitas industriales guiadas por sus modernas instalaciones.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02046','vino','Vinos y bodegas','Integrado en la D.O. Manchuela. Cuenta con bodegas boutique excelentes que combinan la arquitectura tradicional de las casonas manchegas con modernos procesos de viticultura orgánica.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('02039','vino','Vinos y bodegas','Localidad de la D.O. Almansa situada a gran altitud. Es el gran bastión de la uva Garnacha Tintorera, produciendo tintos de un color profundo y gran estructura en cooperativas locales.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('19245','vino','Vinos y bodegas','Pequeño rincón alcarreño donde algunos viticultores independientes mantienen viñedos de secano y elaboran de manera artesanal vinos amparados bajo la denominación de la provincia.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17042','vino','Vinos y bodegas','Es el municipio con mayor concentración de bodegas de la D.O. Empordà. El enoturismo se vive entre masías tradicionales de piedra, rodeadas de viñedos de Cariñena y Garnacha azotados por el viento de Tramuntana.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17064','vino','Vinos y bodegas','Destaca su histórica bodega cooperativa (fundada en 1931), un motor cultural y económico esencial de la zona que ofrece visitas muy completas sobre la historia del vino catalán.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('17128','vino','Vinos y bodegas','Pequeño municipio agrícola donde las viñas conviven con olivos centenarios, dando lugar a cooperativas e industrias locales que elaboran aceites y vinos de altísima calidad.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43098','vino','Vinos y bodegas','Alberga una de las "Catedrales del Vino" modernistas más impresionantes de Cataluña, diseñada por Cèsar Martinell. Su cooperativa industrial sigue activa y ofrece experiencias enoturísticas de gran nivel culinario.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('42008','vino','Vinos y bodegas','Cuenta con otra imponente bodega modernista cooperativa que acoge además el Museo del Vino, un espacio didáctico excepcional para comprender el pasado agrario de la comarca.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('43023','vino','Vinos y bodegas','En plena D.O.C. Priorat. Une la historia de sus antiguas minas de plomo con un paisaje de viñedos verticales de pizarra y bodegas boutique de prestigio mundial.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90860','vino','Vinos y bodegas','Capital del vino en el Valle de Jalón. Famoso por su cooperativa Virgen del Pobre, donde se elaboran espectaculares mistelas y vinos dulces de Moscatel de Alejandría. Es un punto turístico masivo los fines de semana.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('03040','vino','Vinos y bodegas','Gran municipio del interior alicantino con un potente patrimonio de bodegas (como Francisco Gómez o Las Virtudes). Ofrecen imponentes instalaciones industriales orientadas al enoturismo de lujo y al Fondillón histórico.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90381','vino','Vinos y bodegas','Pequeña localidad de secano cuya cooperativa destaca por la producción de tintos de Monastrell de alta graduación natural y una arquitectura de bodega muy funcional.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12128','vino','Vinos y bodegas','Uno de los pueblos más bonitos de España que combina su casco medieval con bodegas singulares que elaboran tintos estructurados con variedades como la Merlot y la Syrah.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('12029','vino','Vinos y bodegas','Municipio que apuesta fuertemente por el micro-enoturismo, albergando pequeñas bodegas familiares ecológicas que ofrecen catas directas en el viñedo.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30012','vino','Vinos y bodegas','Capital de la D.O. Bullas. Cuenta con un Museo del Vino excelente ubicado en una bodega del siglo XIX perfectamente conservada y una red de bodegas familiares subterráneas en el propio casco antiguo.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('30017','vino','Vinos y bodegas','Municipio monumental que cuenta con viñedos de Monastrell de altura y pequeñas bodegas tradicionales de corte familiar integradas en el paisaje de la cuenca del río Mula.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('06122','vino','Vinos y bodegas','Localidad de gran tradición vitícola con bodegas familiares e industriales que destacan por la elaboración de vinos blancos con uvas autóctonas como la Eva o Beba de los Santos.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('90472','vino','Vinos y bodegas','Gran núcleo productor agrícola con inmensas cooperativas preparadas para procesar grandes volúmenes de uva destinados a la exportación a granel y embotellado local.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07008','vino','Vinos y bodegas','Fue el gran motor vinícola de Mallorca en el siglo XIX (llegando a albergar una monumental estación enológica). Hoy conserva espectaculares proyectos de vino de culto (como Anima Negra) metidos en antiguas bodegas de piedra.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07056','vino','Vinos y bodegas','Municipio integrado en la Ruta del Vino de Binissalem. Cuenta con bodegas históricas familiares de gran formato que ofrecen catas de variedades locales junto a la gastronomía tradicional de la isla.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('07018','vino','Vinos y bodegas','Pequeño pueblo del interior mallorquín con bodegas boutique familiares que elaboran producciones muy.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38043','vino','Vinos y bodegas','Capital de la denominación más antigua de las islas. Sus bodegas familiares e industriales están totalmente adaptadas al accidentado relieve canario, elaborando tintos muy minerales de Listán Negro.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38006','vino','Vinos y bodegas','Su propio nombre rinde homenaje a su historia. Combina la visita al famoso Drago Milenario con bodegas tradicionales que elaboran vinos blancos de Malvasía y Listán Blanco en suelos puramente volcánicos.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('38020','vino','Vinos y bodegas','Municipio tinerfeño que produce blancos afrutados de gran altitud. Sus cooperativas controlan viñedos que escalan por la montaña por encima de las nubes.','inventario_vinos_pdf');
INSERT OR IGNORE INTO entidades (codigo_ine,tipo,nombre,descripcion,fuente) VALUES ('35021','vino','Vinos y bodegas','Concentra la mayor tradición vitícola de Gran Canaria, albergando la Casa del Vino de la isla y pequeñas bodegas familiares situadas en el entorno del Monumento Natural de Bandama, cultivando sobre picón volcánico.','inventario_vinos_pdf');
